# connected components for non-background pixels; show bbox and interior output labels
from collections import deque,Counter
seen=set(); comps=[]
for r in range(24):
 for c in range(27):
  color=inp[r][c]
  if color==6 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   rr,cc=q.pop(); cells.append((rr,cc))
   for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
    if 0<=nr<24 and 0<=nc<27 and (nr,nc) not in seen and inp[nr][nc]==color:
     seen.add((nr,nc)); q.append((nr,nc))
  comps.append((color,cells))
[(color,min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells),Counter(out_fixed[r][c] for r in range(min(r for r,c in cells)+1,max(r for r,c in cells)) for c in range(min(c for r,c in cells)+1,max(c for r,c in cells)))) for color,cells in comps]
